              "html": "Some حُرُوْفٌ جَارَّةٌ undergo changes to make pronunciation easier: 1. مِنْ becomes مِنَ if the word after it has an اَلْ: مِنَ الْمَسْجِدِ. 2. عَنْ becomes عَنِ if the word after it has an اَلْ: عَنِ الدَّرْسِ. 3. When لِ comes before a word with an اَلْ, the ا is dropped from that word: اَلرَّجُلُ ← لِلرَّجُلِ. 4. When لِ is placed before the word الله, it is written لِلّٰهِ. 5. When فِيْ is followed by a word with an اَلْ, the ي is not pronounced: فِي الْبَيْتِ. 6. The ي at the end of إِلَى and حَتَّى is pronounced as an أَلِفٌ.",
