              "html": "When a لَا لِنَفْيِ الْجِنْسِ precedes a جُمْلَةٌ اسْمِيَّةٌ: 1. The مُبْتَدَأٌ is called the اِسْمٌ of the لَا لِنَفْيِ الْجِنْسِ and is مَنْصُوْبٌ. Unlike regular nouns, it will only have one فَتْحَةٌ, and no اَلْ nor تَنْوِيْنٌ. 2. The خَبَرٌ is called the خَبَرٌ of the لَا لِنَفْيِ الْجِنْسِ. This is usually a شِبْهُ الْجُمْلَةِ.",
